# ============================================================ helpers
def el_min():
    return (time.time() - T0) / 60.0


def log(*a):
    msg = "[ee %6.1fm] %s" % (el_min(), " ".join(str(x) for x in a))
    print(msg, flush=True)
    with open(os.path.join(OUT, "kernel.log"), "a") as f:
        f.write(msg + "\n")


def event(kind, **kw):
    kw.update(kind=kind, t_min=round(el_min(), 2))
    with open(os.path.join(OUT, "events.jsonl"), "a") as f:
        f.write(json.dumps(kw) + "\n")
    log("EVENT", json.dumps(kw)[:1500])


def sh(cmd, timeout=None, logfile=None, env=None, shell=False):
    """Run; tee to logfile; return (rc, tail)."""
    shown = cmd if isinstance(cmd, str) else " ".join(cmd)
    log("$", shown[:400])
    lf = open(logfile, "a") if logfile else None
    try:
        p = subprocess.run(cmd, shell=shell, env=env, timeout=timeout,
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           text=True, errors="replace")
        out, rc = p.stdout or "", p.returncode
    except subprocess.TimeoutExpired as e:
        out = (e.stdout or b"")
        out = out.decode("utf-8", "replace") if isinstance(out, bytes) else out
        rc = "TIMEOUT"
    if lf:
        lf.write(out)
        lf.close()
    tail = out[-3000:]
    log("rc=%s" % rc, "| tail:", tail[-800:].replace("\n", " \\n "))
    return rc, tail


def disk(tag):
    rep = {}
    for p in ("/", "/tmp", WORK):
        try:
            u = shutil.disk_usage(p)
            rep[p] = "free %.1f GB / %.1f GB" % (u.free / 1e9, u.total / 1e9)
        except Exception as e:
            rep[p] = str(e)
    log("DISK[%s]" % tag, rep)
    return shutil.disk_usage("/tmp").free / 1e9


def rm_hf_cache(repo):
    d = os.path.expanduser("~/.cache/huggingface/hub/models--%s" % repo.replace("/", "--"))
    if os.path.isdir(d):
        shutil.rmtree(d, ignore_errors=True)
        log("removed HF cache", d)


