def start_llamacpp_tools():
    """Background CPU build of llama-quantize + the converter scripts at the SAME
    tag as the attached llama-server (converter/server format parity)."""
    script = r"""
set -x
cd /tmp && rm -rf llama.cpp
git clone --depth 1 --branch %s https://github.com/ggml-org/llama.cpp /tmp/llama.cpp || exit 11
cd /tmp/llama.cpp
cmake -B build -DGGML_CUDA=OFF -DLLAMA_CURL=OFF -DBUILD_SHARED_LIBS=OFF \
      -DCMAKE_BUILD_TYPE=Release -DGGML_NATIVE=ON || exit 12
cmake --build build --config Release --target llama-quantize -j2 || exit 13
ls -la build/bin/llama-quantize && echo QUANTIZE_OK
""" % LLAMACPP_TAG
    lf = open(os.path.join(OUT, "llamacpp-tools.log"), "w")
    log("background: llama.cpp %s clone + llama-quantize CPU build" % LLAMACPP_TAG)
    return subprocess.Popen(["bash", "-c", script], stdout=lf, stderr=subprocess.STDOUT)


def install():
    rc, tv = sh([PY, "-c", "import importlib.metadata as m\n"
                 "for p in ('torch','torchvision','torchaudio'):\n"
                 "  try: print(p+'=='+m.version(p))\n"
                 "  except Exception: pass"])
    cons = os.path.join(TMP, "constraints.txt")
    pins = [l.strip() for l in tv.splitlines() if "==" in l and l.strip().split("==")[0]
            in ("torch", "torchvision", "torchaudio")]
    open(cons, "w").write("\n".join(pins) + "\n")
    log("torch constraints:", pins)
    plog = os.path.join(OUT, "pip-install.log")
    rc, _ = sh([PY, "-m", "pip", "install", "-q", "-c", cons, "--only-binary=xformers"]
               + PINS, timeout=1500, logfile=plog)
    route = "A:resolve-with-torch-constraints"
    if rc != 0:
        route = "B:no-deps"
        sh([PY, "-m", "pip", "install", "-q", "--no-deps", PINS[0], PINS[1]],
           timeout=600, logfile=plog)
        sh([PY, "-m", "pip", "install", "-q", "-c", cons] + PINS[2:] + NODEPS_EXTRA,
           timeout=1500, logfile=plog)
    chk = ("import torch, transformers, peft, trl, bitsandbytes, accelerate\n"
           "import unsloth, unsloth_zoo\n"
           "import importlib.metadata as m, json\n"
           "v={p:m.version(p) for p in ['unsloth','unsloth_zoo','torch','transformers','peft',"
           "'trl','bitsandbytes','accelerate','datasets','triton']}\n"
           "for p in ['xformers','cut_cross_entropy','torchao']:\n"
           "  try: v[p]=m.version(p)\n"
           "  except Exception: v[p]=None\n"
           "v['cuda']=torch.version.cuda; v['gpu']=torch.cuda.get_device_name(0)\n"
           "print('VERSIONS_JSON='+json.dumps(v))\n")
    for attempt in range(3):
        rc, tail = sh([PY, "-c", chk], timeout=600, logfile=plog)
        if rc == 0:
            break
        miss = re.findall(r"No module named '([A-Za-z0-9_\.]+)'", tail)
        if not miss:
            break
        mod = miss[-1].split(".")[0].replace("_", "-")
        log("import check: missing module", mod, "-> pip install")
        sh([PY, "-m", "pip", "install", "-q", "-c", cons, mod], timeout=600, logfile=plog)
    m = re.search(r"VERSIONS_JSON=(\{.*\})", tail)
    versions = json.loads(m.group(1)) if m else None
    event("install", route=route, rc=rc, versions=versions, torch_constraints=pins)
    sh("pip freeze", shell=True, logfile=os.path.join(OUT, "pip-freeze.txt"))
    return rc == 0


