TRIAL_PY = r'''
import os, sys, json, time, argparse, traceback, gc, statistics
ap = argparse.ArgumentParser()
ap.add_argument("--model"); ap.add_argument("--tag"); ap.add_argument("--rows")
ap.add_argument("--seqs"); ap.add_argument("--steps"); ap.add_argument("--out")
ap.add_argument("--backend", default="unsloth"); ap.add_argument("--device-map", default="single")
ap.add_argument("--save-lora", default="")
a = ap.parse_args()
seqs = [int(s) for s in a.seqs.split(",")]; steps = [int(s) for s in a.steps.split(",")]
TARGETS = %(targets)r

def emit(**kw):
    kw.update(tag=a.tag, model=a.model, backend=a.backend, device_map=a.device_map)
    with open(a.out, "a") as f: f.write(json.dumps(kw) + "\n")
    print("EMIT", json.dumps(kw), flush=True)

def is_oom(e):
    s = (type(e).__name__ + " " + str(e)).lower()
    return "out of memory" in s or "outofmemory" in s or "cuda_error_out_of_memory" in s

import torch
ndev = torch.cuda.device_count()
GiB = 1024 ** 3
rows = json.load(open(a.rows))
t0 = time.time()
try:
    if a.backend == "unsloth":
        from unsloth import FastLanguageModel
        kw = dict(model_name=a.model, max_seq_length=max(seqs), load_in_4bit=True, dtype=None)
        if a.device_map == "balanced":
            kw["device_map"] = "balanced"
        model, tok = FastLanguageModel.from_pretrained(**kw)
        model = FastLanguageModel.get_peft_model(
            model, r=16, lora_alpha=16, lora_dropout=0, bias="none", target_modules=TARGETS,
            use_gradient_checkpointing="unsloth", random_state=3407)
        try:
            FastLanguageModel.for_training(model)
        except Exception:
            model.train()
    else:
        from transformers import AutoModelForCausalLM, AutoTokenizer
        from peft import LoraConfig, get_peft_model
        mm = {i: "13GiB" for i in range(ndev)}
        model = AutoModelForCausalLM.from_pretrained(a.model, device_map="auto",
                                                     dtype=torch.float16, max_memory=mm)
        tok = AutoTokenizer.from_pretrained(a.model)
        model.config.use_cache = False
        model.gradient_checkpointing_enable(gradient_checkpointing_kwargs={"use_reentrant": False})
        model.enable_input_require_grads()
        model = get_peft_model(model, LoraConfig(r=16, lora_alpha=16, lora_dropout=0.0,
                                                 target_modules=TARGETS, task_type="CAUSAL_LM"))
        model.train()
except Exception as e:
    emit(phase="load", status="OOM" if is_oom(e) else "ERROR", error=repr(e)[:1500],
         tb=traceback.format_exc()[-3000:], load_s=round(time.time() - t0, 1))
    sys.exit(3)

params = [p for p in model.parameters() if p.requires_grad]
for p in params:
    if p.dtype != torch.float32:
        p.data = p.data.float()
n_train = sum(p.numel() for p in params)
wdt = str(getattr(model, "dtype", "?"))
load_mem = [round(torch.cuda.memory_allocated(d) / GiB, 3) for d in range(ndev)]
tot_mem = [round(torch.cuda.get_device_properties(d).total_memory / GiB, 3) for d in range(ndev)]
emit(phase="load", status="OK", load_s=round(time.time() - t0, 1), trainable=n_train,
     model_dtype=wdt, mem_after_load_gib=load_mem, gpu_total_gib=tot_mem,
     hf_device_map_devices=sorted(set(str(v) for v in (getattr(model, "hf_device_map", None) or {}).values()))[:8])

enc = lambda s: tok(s, add_special_tokens=False)["input_ids"]
TH = enc("<think>\n")

def build(row, seq):
    P = enc("<|im_start|>system\n%%s<|im_end|>\n<|im_start|>user\n%%s<|im_end|>\n<|im_start|>assistant\n"
            %% (row["system"], row["user"]))
    A = enc("\n</think>\n\n" + row["answer"] + "<|im_end|>\n")
    seed = enc(row["think_seed"] + "\n\n")
    n = seq - len(P) - len(TH) - len(A)
    if n < 0:
        A = A[:len(A) + n]; n = 0
    think = (seed * (n // max(1, len(seed)) + 1))[:n]
    ids = P + TH + think + A
    return ids, [-100] * len(P) + ids[len(P):], len(P), len(A)

plen = [len(enc("<|im_start|>system\n%%s<|im_end|>\n<|im_start|>user\n%%s<|im_end|>\n<|im_start|>assistant\n"
                %% (r["system"], r["user"]))) for r in rows]
alen = [len(enc(r["answer"])) for r in rows]
emit(phase="tokens", prompt_tokens_mean=round(sum(plen) / len(plen), 1), prompt_tokens_max=max(plen),
     prompt_tokens_min=min(plen), answer_tokens_mean=round(sum(alen) / len(alen), 1), n_rows=len(rows))

import bitsandbytes as bnb
opt = bnb.optim.AdamW8bit(params, lr=2e-4, weight_decay=0.0)
scaler = torch.amp.GradScaler("cuda")
dev0 = model.get_input_embeddings().weight.device
any_pass = False
blocked = False
for seq, nst in zip(seqs, steps):
    if blocked:
        emit(phase="train", seq=seq, status="SKIPPED", reason="smaller seq already failed")
        continue
    gc.collect(); torch.cuda.empty_cache()
    for d in range(ndev):
        torch.cuda.reset_peak_memory_stats(d)
    times, losses, status, err = [], [], "PASS", None
    for i in range(nst):
        ids, lab, lp, la = build(rows[i %% len(rows)], seq)
        assert len(ids) == seq, (len(ids), seq)
        x = torch.tensor([ids], device=dev0); y = torch.tensor([lab], device=dev0)
        try:
            for d in range(ndev):
                torch.cuda.synchronize(d)
            t = time.time()
            with torch.autocast("cuda", dtype=torch.float16):
                out = model(input_ids=x, labels=y)
            loss = out.loss
            scaler.scale(loss).backward()
            scaler.step(opt); scaler.update(); opt.zero_grad(set_to_none=True)
            for d in range(ndev):
                torch.cuda.synchronize(d)
            dt = time.time() - t
            lv = float(loss.detach().float().item())
            times.append(round(dt, 2)); losses.append(round(lv, 4))
            print("STEP seq=%%d i=%%d dt=%%.2fs loss=%%.4f peak=%%s" %% (seq, i, dt, lv,
                  [round(torch.cuda.max_memory_allocated(d) / GiB, 2) for d in range(ndev)]), flush=True)
            del out, loss
        except Exception as e:
            status = "OOM" if is_oom(e) else "ERROR"
            err = repr(e)[:1500]
            print(traceback.format_exc()[-3000:], flush=True)
            opt.zero_grad(set_to_none=True)
            break
        finally:
            del x, y
    peak = [round(torch.cuda.max_memory_allocated(d) / GiB, 3) for d in range(ndev)]
    peak_res = [round(torch.cuda.max_memory_reserved(d) / GiB, 3) for d in range(ndev)]
    finite = all(l == l and abs(l) != float("inf") for l in losses)
    if status == "PASS" and not finite:
        status = "NAN"
    steady = times[1:] if len(times) > 1 else times
    emit(phase="train", seq=seq, steps_req=nst, steps_done=len(times), status=status, error=err,
         peak_alloc_gib=peak, peak_alloc_gib_max=max(peak), peak_reserved_gib=peak_res,
         s_per_step=times, s_per_step_median=(round(statistics.median(steady), 2) if steady else None),
         first_step_s=(times[0] if times else None), losses=losses, loss_finite=finite,
         scaler_scale=float(scaler.get_scale()))
    if status == "PASS":
        any_pass = True
    else:
        blocked = True
        gc.collect(); torch.cuda.empty_cache()

if a.save_lora and any_pass:
    try:
        model.save_pretrained(a.save_lora); tok.save_pretrained(a.save_lora)
        sz = sum(os.path.getsize(os.path.join(dp, f)) for dp, _, fs in os.walk(a.save_lora) for f in fs)
        emit(phase="save_lora", status="OK", dir=a.save_lora, bytes=sz)
    except Exception as e:
        emit(phase="save_lora", status="ERROR", error=repr(e)[:1500])
''' % dict(targets=TARGETS)


def trial(tag, model, seqs, steps, backend="unsloth", device_map="single",
          timeout_min=45):
    tfile = os.path.join(OUT, "trials.jsonl")
    before = open(tfile).read().count("\n") if os.path.exists(tfile) else 0
    env = dict(os.environ, PYTORCH_CUDA_ALLOC_CONF="expandable_segments:True",
               TOKENIZERS_PARALLELISM="false")
    env["CUDA_VISIBLE_DEVICES"] = "0" if device_map == "single" else "0,1"
    lora = os.path.join(TMP, "lora-" + tag)
    cmd = [PY, os.path.join(TMP, "ee_trial.py"), "--model", model, "--tag", tag,
           "--rows", os.path.join(TMP, "rows.json"),
           "--seqs", ",".join(map(str, seqs)), "--steps", ",".join(map(str, steps)),
           "--out", tfile, "--backend", backend, "--device-map", device_map,
           "--save-lora", lora]
    log("TRIAL", tag, model, seqs, steps, backend, device_map)
    rc, tail = sh(cmd, timeout=timeout_min * 60, env=env,
                  logfile=os.path.join(OUT, "trial-%s.log" % tag))
    recs = []
    if os.path.exists(tfile):
        recs = [json.loads(l) for l in open(tfile).read().splitlines()[before:] if l.strip()]
    if rc == "TIMEOUT":
        event("trial_timeout", tag=tag, timeout_min=timeout_min)
    passed = {r["seq"] for r in recs if r.get("phase") == "train" and r.get("status") == "PASS"}
    load = [r for r in recs if r.get("phase") == "load"]
    load_err = bool(load) and load[0].get("status") != "OK"
    return dict(tag=tag, model=model, rc=rc, passed=sorted(passed), recs=recs,
                load_error=load_err, lora=lora if os.path.isdir(lora) else None,
                load_status=(load[0].get("status") if load else "NO_LOAD_RECORD"))


