def find_server():
    hits = sorted(glob.glob("/kaggle/input/**/llamacpp/bin/llama-server", recursive=True))
    tars = sorted(glob.glob("/kaggle/input/**/llamacpp.tar.gz", recursive=True))
    dst = os.path.join(TMP, "llamacpp")
    if not os.path.isdir(dst):
        if hits:
            shutil.copytree(os.path.dirname(os.path.dirname(hits[0])), dst)
        elif tars:
            sh(["tar", "-xzf", tars[0], "-C", TMP])
        sh("chmod +x %s/bin/* || true" % dst, shell=True)
    srv = os.path.join(dst, "bin", "llama-server")
    return srv if os.path.isfile(srv) else None


def wait_health(proc, timeout=900):
    url = "http://127.0.0.1:%d/health" % PORT
    t0 = time.time()
    while time.time() - t0 < timeout:
        if proc.poll() is not None:
            return False
        try:
            with urllib.request.urlopen(url, timeout=5) as r:
                if r.status == 200:
                    return True
        except Exception:
            pass
        time.sleep(3)
    return False


def post(path, body, timeout=600):
    req = urllib.request.Request("http://127.0.0.1:%d%s" % (PORT, path),
                                 data=json.dumps(body).encode(),
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode())


PROBE = ("In one sentence, what does a cascode transistor do in a low-noise "
         "amplifier? /no_think")


def serve_and_generate(tag, gguf, lora_gguf=None, ngl_split=False):
    srv = find_server()
    if not srv:
        return dict(status="NO_SERVER")
    cmd = [srv, "-m", gguf, "--host", "127.0.0.1", "--port", str(PORT),
           "--n-gpu-layers", "999", "-c", "4096", "--parallel", "1"]
    if ngl_split:
        cmd += ["--split-mode", "layer"]
    if lora_gguf:
        cmd += ["--lora", lora_gguf]
    slog = os.path.join(OUT, "llama-server-%s.log" % tag)
    log("launching", " ".join(cmd))
    env = dict(os.environ)
    env["CUDA_VISIBLE_DEVICES"] = "0,1" if ngl_split else "0"
    proc = subprocess.Popen(cmd, stdout=open(slog, "w"), stderr=subprocess.STDOUT, env=env)
    res = dict(status="LOAD_FAIL", gguf=os.path.basename(gguf),
               gguf_bytes=os.path.getsize(gguf), lora=bool(lora_gguf))
    try:
        t = time.time()
        if not wait_health(proc):
            res["server_log_tail"] = open(slog).read()[-2500:]
            return res
        res["load_s"] = round(time.time() - t, 1)
        body = dict(messages=[{"role": "user", "content": PROBE}], max_tokens=96,
                    temperature=0.0, seed=1)
        r1 = post("/v1/chat/completions", body)
        msg = r1["choices"][0]["message"]
        res.update(status="OK", completion=(msg.get("content") or "")[:600],
                   reasoning=(msg.get("reasoning_content") or "")[:300],
                   usage=r1.get("usage"))
        if lora_gguf:
            try:
                res["lora_adapters"] = json.loads(urllib.request.urlopen(
                    "http://127.0.0.1:%d/lora-adapters" % PORT, timeout=10).read().decode())
                post("/lora-adapters", [{"id": 0, "scale": 0.0}])
                r0 = post("/v1/chat/completions", body)
                res["completion_lora_scale0"] = (r0["choices"][0]["message"].get("content") or "")[:600]
                res["lora_changes_output"] = res["completion_lora_scale0"] != res["completion"]
            except Exception as e:
                res["lora_scale_probe_error"] = repr(e)[:400]
        sl = open(slog).read()
        res["server_log_lora_lines"] = [l for l in sl.splitlines() if "lora" in l.lower()][:8]
        res["server_version"] = [l for l in sl.splitlines() if "build" in l.lower()][:2]
        return res
    except Exception as e:
        res.update(status="GEN_ERROR", error=repr(e)[:800])
        return res
    finally:
        if proc.poll() is None:
            proc.send_signal(signal.SIGTERM)
            try:
                proc.wait(timeout=20)
            except Exception:
                proc.kill()


def llamacpp_ready(bg, wait_min=20):
    t = time.time()
    while bg.poll() is None and time.time() - t < wait_min * 60:
        time.sleep(10)
    ok_conv = os.path.isfile("/tmp/llama.cpp/convert_hf_to_gguf.py")
    q = "/tmp/llama.cpp/build/bin/llama-quantize"
    return ok_conv, (q if os.path.isfile(q) else None)


def run_convert(script_args, logname):
    """Run a llama.cpp converter; auto-install one missing python module per retry."""
    cons = os.path.join(TMP, "constraints.txt")
    for _ in range(4):
        rc, tail = sh([PY] + script_args, timeout=3600,
                      logfile=os.path.join(OUT, logname))
        if rc == 0:
            return True
        miss = re.findall(r"No module named '([A-Za-z0-9_\.]+)'", tail)
        if not miss:
            return False
        mod = miss[-1].split(".")[0].replace("_", "-")
        sh([PY, "-m", "pip", "install", "-q", "-c", cons, mod], timeout=600)
    return False


def roundtrip_merged(tr, bg):
    tag = tr["tag"]
    res = dict(route="merged", tag=tag, model=tr["model"])
    merged = os.path.join(TMP, "merged-" + tag)
    open(os.path.join(TMP, "ee_merge.py"), "w").write(MERGE_PY)
    free = disk("pre-merge")
    t = time.time()
    rc, tail = sh([PY, os.path.join(TMP, "ee_merge.py"), tr["lora"], merged], timeout=3600,
                  env=dict(os.environ, CUDA_VISIBLE_DEVICES="0"),
                  logfile=os.path.join(OUT, "rt-merge-%s.log" % tag))
    res["merge_rc"], res["merge_s"] = rc, round(time.time() - t, 1)
    if rc != 0 or not glob.glob(os.path.join(merged, "*.safetensors")):
        res["status"] = "MERGE_FAIL"
        res["tail"] = tail[-1200:]
        return res
    res["merged_bytes"] = sum(os.path.getsize(f) for f in glob.glob(os.path.join(merged, "*")))
    # the 16-bit source weights unsloth downloaded for the merge are no longer needed
    for c in glob.glob(os.path.expanduser("~/.cache/huggingface/hub/models--Qwen--Qwen3-*")):
        shutil.rmtree(c, ignore_errors=True)
    free = disk("post-merge")
    ok_conv, quant = llamacpp_ready(bg)
    if not ok_conv:
        res["status"] = "NO_CONVERTER"
        return res
    outtype = "f16" if free > res["merged_bytes"] / 1e9 * 1.15 + 5 else "q8_0"
    g1 = os.path.join(TMP, "%s-%s.gguf" % (tag, outtype))
    t = time.time()
    ok = run_convert(["/tmp/llama.cpp/convert_hf_to_gguf.py", merged, "--outtype", outtype,
                      "--outfile", g1], "rt-convert-%s.log" % tag)
    res["convert_outtype"], res["convert_s"] = outtype, round(time.time() - t, 1)
    shutil.rmtree(merged, ignore_errors=True)
    if not ok or not os.path.isfile(g1):
        res["status"] = "CONVERT_FAIL"
        return res
    gq = g1
    if quant:
        g2 = os.path.join(TMP, "%s-Q4_K_M.gguf" % tag)
        t = time.time()
        qargs = [quant] + (["--allow-requantize"] if outtype == "q8_0" else []) + \
            [g1, g2, "Q4_K_M", str(os.cpu_count() or 4)]
        rc, _ = sh(qargs, timeout=3600, logfile=os.path.join(OUT, "rt-quantize-%s.log" % tag))
        res["quantize_rc"], res["quantize_s"] = rc, round(time.time() - t, 1)
        if rc == 0 and os.path.isfile(g2):
            gq = g2
            os.remove(g1)
    res["quant_type"] = "Q4_K_M" if gq.endswith("Q4_K_M.gguf") else outtype
    res["serve"] = serve_and_generate(tag, gq)
    res["status"] = "OK" if res["serve"].get("status") == "OK" and res["quant_type"] == "Q4_K_M" \
        else ("SERVED_UNQUANTIZED" if res["serve"].get("status") == "OK" else "SERVE_FAIL")
    try:
        os.remove(gq)
    except Exception:
        pass
    return res


OFFICIAL_GGUF = {"14B": ("Qwen/Qwen3-14B-GGUF", "Qwen3-14B-Q4_K_M.gguf"),
                 "8B": ("Qwen/Qwen3-8B-GGUF", "Qwen3-8B-Q4_K_M.gguf")}


def roundtrip_adapter(tr, bg):
    """Runtime-LoRA route: base Q4 GGUF + LoRA GGUF in llama-server. 32B uses our
    attached proposer GGUF; 14B/8B (fallback only) download the official Q4_K_M."""
    tag = tr["tag"]
    res = dict(route="adapter", tag=tag, model=tr["model"])
    size = "32B" if "32B" in tr["model"] else ("14B" if "14B" in tr["model"] else "8B")
    if size == "32B":
        base = sorted(glob.glob("/kaggle/input/**/Qwen3-32B*.gguf", recursive=True))
    else:
        repo, fn = OFFICIAL_GGUF[size]
        rc, tail = sh([PY, "-c", "from huggingface_hub import hf_hub_download as d;"
                       "print('GGUF_PATH='+d(%r,%r,local_dir=%r))" % (repo, fn, TMP)],
                      timeout=1800)
        m = re.search(r"GGUF_PATH=(\S+)", tail)
        base = [m.group(1)] if m else []
    if not base:
        res["status"] = "NO_BASE_GGUF"
        return res
    ok_conv, _ = llamacpp_ready(bg)
    if not ok_conv:
        res["status"] = "NO_CONVERTER"
        return res
    snap = glob.glob(os.path.expanduser("~/.cache/huggingface/hub/models--%s/snapshots/*"
                                        % tr["model"].replace("/", "--")))
    lg = os.path.join(TMP, "lora-%s.gguf" % tag)
    args = ["/tmp/llama.cpp/convert_lora_to_gguf.py", tr["lora"], "--outtype", "f16",
            "--outfile", lg]
    args += (["--base", snap[0]] if snap else ["--base-model-id", tr["model"]])
    t = time.time()
    ok = run_convert(args, "rt-convert-lora-%s.log" % tag)
    res["convert_s"] = round(time.time() - t, 1)
    if not ok or not os.path.isfile(lg):
        res["status"] = "CONVERT_FAIL"
        return res
    res["lora_gguf_bytes"] = os.path.getsize(lg)
    res["base_gguf"] = os.path.basename(base[0])
    res["serve"] = serve_and_generate(tag, base[0], lora_gguf=lg, ngl_split=(size == "32B"))
    res["status"] = "OK" if res["serve"].get("status") == "OK" else "SERVE_FAIL"
    if size != "32B":
        try:
            os.remove(base[0])
        except Exception:
            pass
    return res


# ============================================================ main
def ok4096(tr):
    return tr is not None and 4096 in tr["passed"]


def main():
    os.makedirs(OUT, exist_ok=True)
    os.makedirs(TMP, exist_ok=True)
    summary = dict(prereg="kaggle/PREREG-BENCH-V12-AUDIT.md#E-e", budget_min=BUDGET_MIN,
                   trials=[], roundtrips=[])
    try:
        rows = json.loads(zlib.decompress(base64.b64decode(ROWS_B64)).decode())
        assert rows and all(r["source_lib"] == "editcap-lib-v1a" for r in rows)
        assert not any(r["cell"].startswith("v12-") for r in rows), "FENCE"
        json.dump(rows, open(os.path.join(TMP, "rows.json"), "w"))
        open(os.path.join(TMP, "ee_trial.py"), "w").write(TRIAL_PY)
        log("rows:", len(rows), "cells", [r["cell"] for r in rows][:5], "...")
        env_log()
        disk("start")
        bg = start_llamacpp_tools()
        if not install():
            summary["verdict"] = "INSTALL_FAILED"
            return
        trials = {}

        def run(tag, *a, **k):
            if el_min() > BUDGET_MIN - 20:
                event("skip_trial", tag=tag, reason="budget")
                return None
            tr = trial(tag, *a, **k)
            trials[tag] = tr
            summary["trials"].append({k2: v for k2, v in tr.items() if k2 != "recs"})
            json.dump(summary, open(os.path.join(OUT, "summary.json"), "w"), indent=1)
            return tr

        t14 = run("q14dyn", M14_DYN, [4096, 8192], [10, 10])
        best14 = t14 if ok4096(t14) else None
        need = [s for s in (4096, 8192) if not (t14 and s in t14["passed"])]
        if need:
            t14p = run("q14plain", M14_PLAIN, need, [10] * len(need))
            # plain wins if it covers seqs the dynamic quant could not (it is
            # re-tried only on the failed seqs, so any pass there is coverage)
            if t14p is not None and t14p["passed"] and (
                    best14 is None and ok4096(t14p) or best14 is not None and 8192 in t14p["passed"]):
                if best14 is not None:  # re-run it at 4096 too? no: 8192 pass implies 4096 fits
                    t14p["passed"] = sorted(set(t14p["passed"]) | {4096})
                    t14p["note"] = "4096 not re-run: dynamic-quant 14B passed 4096 and plain is smaller"
                best14 = t14p
            rm_hf_cache(M14_PLAIN if best14 is not t14p else M14_DYN)
        winner = best14
        if best14 is None:
            t8 = run("q8dyn", M8_DYN, [4096, 8192], [10, 10])
            winner = t8 if ok4096(t8) else None
            if winner is None:
                summary["verdict"] = "NO_MODEL_>=8B_TRAINS_AT_4096 (floor hit: stop and ask)"
        big = None
        if best14 is not None:
            if el_min() < 60:
                disk("pre-32B")
                t32 = run("q32split", M32_PLAIN, [4096, 8192], [5, 3],
                          device_map="balanced", timeout_min=50)
                if t32 is not None and t32["load_error"] and el_min() < 75:
                    log("unsloth balanced split failed at load -> HF+peft device_map=auto")
                    t32 = run("q32hf", M32_PLAIN, [4096, 8192], [5, 3], backend="hf",
                              device_map="balanced", timeout_min=45)
                if ok4096(t32):
                    big = t32
            else:
                event("skip_32b", reason="elapsed %.0f min >= 60" % el_min())
        # ---- round trip(s)
        disk("pre-roundtrip")
        if big is not None and big.get("lora"):
            summary["roundtrips"].append(roundtrip_adapter(big, bg))
            json.dump(summary, open(os.path.join(OUT, "summary.json"), "w"), indent=1)
            rm_hf_cache(M32_PLAIN)
        if winner is not None and winner.get("lora"):
            if el_min() < BUDGET_MIN - 35:
                rt = roundtrip_merged(winner, bg)
                summary["roundtrips"].append(rt)
                json.dump(summary, open(os.path.join(OUT, "summary.json"), "w"), indent=1)
                if rt.get("status") not in ("OK", "SERVED_UNQUANTIZED") and big is None \
                        and el_min() < BUDGET_MIN - 12:
                    log("merged round trip failed (%s) -> runtime-LoRA fallback" % rt.get("status"))
                    for c in glob.glob(os.path.expanduser(
                            "~/.cache/huggingface/hub/models--Qwen--Qwen3-*")):
                        shutil.rmtree(c, ignore_errors=True)
                    shutil.rmtree(os.path.join(TMP, "merged-" + winner["tag"]), ignore_errors=True)
                    summary["roundtrips"].append(roundtrip_adapter(winner, bg))
            else:
                event("skip_merged_roundtrip", reason="budget", tag=winner["tag"])
        largest = big or winner
        if largest is not None:
            summary["verdict"] = dict(largest_trainable=largest["model"], tag=largest["tag"],
                                      seqs_passed=largest["passed"])
    except Exception:
        summary["fatal"] = traceback.format_exc()[-3000:]
        log("FATAL", summary["fatal"])
    finally:
        summary["elapsed_min"] = round(el_min(), 1)
        json.dump(summary, open(os.path.join(OUT, "summary.json"), "w"), indent=1)
        log("SUMMARY", json.dumps(summary)[:4000])


if __name__ == "__main__":
    main()
